/* Singlite Single · this VPS, simple connections. */
(() => {
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const storageKey='singlite-single-v3',GB=1e9;
const pages={nodes:'节点管理',users:'用户管理',conversions:'订阅转换',logs:'运行日志',settings:'面板设置'};
const state={mode:'loading',csrf:'',page:pages[location.hash.slice(1)]?location.hash.slice(1):'nodes',nodes:[],users:[],conversions:[],settings:{},core:{},machine:{},filter:'all',search:'',logs:[],modal:null};
let busy=false,polling=false,returnFocus=null;
class ApiError extends Error{constructor(message,status=0){super(message);this.status=status;}}
async function request(path,options={}){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);
 try{
  const headers={Accept:'application/json',...options.headers};
  if(options.body!==undefined)headers['Content-Type']='application/json';
  if(options.method&&options.method!=='GET'&&state.csrf)headers['X-CSRF-Token']=state.csrf;
  const r=await fetch(path,{credentials:'same-origin',...options,body:options.body===undefined?undefined:JSON.stringify(options.body),headers,signal:controller.signal});
  let data;try{data=await r.json();}catch{throw new ApiError('无法识别服务器响应，请检查面板版本。',r.status);}
  if(!r.ok)throw new ApiError(data.error||`服务器返回 ${r.status}`,r.status);return data;
 }catch(e){if(e instanceof ApiError)throw e;throw new ApiError(e.name==='AbortError'?'连接超时，请稍后重试。':'无法连接面板，请检查网络和服务。');}finally{clearTimeout(timeout);}
}

async function bootstrap(){
 closeModal();$('#app').hidden=true;$('#gate').hidden=false;$('#gate').innerHTML='<div class="initial-loading"><span class="loader"></span><span>正在连接 Singlite…</span></div>';
 const c=new AbortController(),t=setTimeout(()=>c.abort(),12000);
 try{
  const r=await fetch('/api/bootstrap',{credentials:'same-origin',signal:c.signal}),body=await r.text();
  if(location.hostname.endsWith('.chatgpt.site')&&(r.status===404||(r.ok&&/(?:<!doctype\s+html|<html[\s>])/i.test(body)))){startDemo();return;}
  if(!r.ok)throw new Error(`面板暂时不可用（HTTP ${r.status}）`);
  const b=JSON.parse(body);if(b.mode!=='live'||b.edition!=='single')throw new Error('面板版本不兼容');state.mode='live';state.csrf=b.csrf||'';
  if(b.setupRequired){gate('完成管理员初始化','请按部署包 README 的管理员初始化说明，在 VPS 终端创建管理员。');return;}
  if(!b.authenticated){login();return;}await refreshState();showApp();
 }catch(e){gate('暂时无法连接',e.name==='AbortError'?'连接超时，请检查服务器。':e.message,true);}finally{clearTimeout(t);}
}
function brand(){return '<div class="brand"><span class="brand-symbol">ϟ</span><span class="brand-text">singlite<span>轻量 · 自由 · 连接</span></span></div>';}
function gate(title,message,retry=false){$('#app').hidden=true;$('#gate').hidden=false;$('#gate').innerHTML=`<div class="gate-card">${brand()}<h1>${esc(title)}</h1><p class="gate-description">${esc(message)}</p>${retry?'<button class="button primary" data-action="retry">重新连接</button>':''}<div class="gate-footer">连接失败时不会切换成演示数据。</div></div>`;}
function login(error=''){
 $('#app').hidden=true;$('#gate').hidden=false;$('#gate').innerHTML=`<div class="gate-card">${brand()}<h1>欢迎回来</h1><p class="gate-description">一处管理，每一次连接。</p><form id="login-form">${error?`<div class="form-error" role="alert">${esc(error)}</div>`:''}<div class="form-field"><label for="username">用户名</label><input class="input" id="username" name="username" value="admin" autocomplete="username" required></div><div class="form-field"><label for="password">密码</label><input class="input" id="password" name="password" type="password" autocomplete="current-password" required></div><button class="button primary" type="submit">${icon('lock')}登录面板</button></form><div class="gate-footer">管理员账号在 VPS 安装时创建。</div></div>`;
}
const freshId=()=>crypto.randomUUID().replaceAll('-','');
function seedDemo(){return {nodes:[{id:'demo-reality',name:'Reality · 主线路',protocol:'vless',port:8443,enabled:true,sni:'www.amd.com'},{id:'demo-ss',name:'SS2022 · 备用',protocol:'shadowsocks',port:8388,enabled:true,method:'2022-blake3-aes-128-gcm'}],users:[{id:'demo-user',name:'我的账号',note:'独立身份 · 双向配额',enabled:true,quotaBytes:100*GB,uploadBytes:0,downloadBytes:0,cycle:'monthly',resetDay:1,nodeIds:['*'],expiresAt:null}],settings:{publicHost:'vps.example.com'},core:{version:'sing-box',service:'inactive',ready:false,accounting:'unavailable'},machine:{hostname:'我的 VPS'},logs:[]};}
function startDemo(){let saved;try{saved=JSON.parse(localStorage.getItem(storageKey));}catch{}const now=Math.floor(Date.now()/1000);Object.assign(state,saved&&Array.isArray(saved.nodes)&&Array.isArray(saved.users)?saved:seedDemo(),{mode:'demo',csrf:'',conversions:[{id:'demo-conversion',name:'HK 手工节点 · 示例',nodeCount:2,createdAt:now,updatedAt:now}]});showApp();}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({nodes:state.nodes,users:state.users,settings:state.settings,core:state.core,machine:state.machine,logs:state.logs.slice(-100)}));}catch{toast('浏览器存储不可用，本次修改只保留在当前页面。',true);}}
function eventLog(message){state.logs.push(new Date().toLocaleString()+' [演示] '+message);persist();}
async function refreshState(){const d=await request('/api/state');if(d.edition!=='single'||!Array.isArray(d.nodes))throw new ApiError('请使用单机版面板后端。');Object.assign(state,d,{conversions:Array.isArray(d.conversions)?d.conversions:[]});state.mode='live';}
function showApp(){$('#gate').hidden=true;$('#app').hidden=false;render();}

function bytes(v){if(!Number.isFinite(v))return'—';const units=['B','KB','MB','GB','TB'];let i=0;while(v>=1000&&i<4){v/=1000;i++;}return`${v<10&&i?v.toFixed(2):v.toFixed(i?1:0)} ${units[i]}`;}
function remainingBytes(u){return u.quotaBytes?Math.max(0,u.quotaBytes-u.uploadBytes-u.downloadBytes):null;}
function trafficGB(v){return v===null?'不限量':v>0&&v<GB/100?'不足 0.01 GB':`${(v/GB).toFixed(2)} GB`;}
function date(v){return v?new Date(v*1000).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}):'长期有效';}
function userStatus(u){if(!u.enabled)return'disabled';if(u.expiresAt&&u.expiresAt<Date.now()/1000)return'expired';if(u.quotaBytes&&(u.uploadBytes+u.downloadBytes)>=u.quotaBytes)return'quota';return'active';}
const statusText={active:'可用',disabled:'已停用',expired:'已到期',quota:'额度用尽'};
function heading(title,desc,action,label,symbol='plus'){return `<div class="page-heading"><div><div class="eyebrow">ONE VPS. SIMPLE CONNECTION.</div><h1>${title}</h1><p>${desc}</p></div>${action?`<button class="button primary" data-action="${action}">${icon(symbol)}${label}</button>`:''}</div>`;}
function banner(){if(state.mode==='demo')return `<div class="notice">${icon('info')}<span>单机版交互预览。节点和流量为示例，修改仅保存在当前浏览器。</span><button class="text-button" data-action="guide">部署到我的 VPS ${icon('arrow')}</button></div>`;if(state.core.error)return `<div class="notice error-notice">${icon('info')}<span>${esc(state.core.error)}</span><button class="text-button" data-action="goto" data-page="logs">查看日志</button></div>`;if(!state.core.ready)return `<div class="notice">${icon('info')}<span>${state.running?'正在应用节点配置或检查统计；各节点独立运行。':'本机核心已暂停，可在下方重新启动。'}</span></div>`;return '';}
function metrics(){return `<div class="metrics">${[['power','本机核心',state.mode==='demo'?'待部署':state.core.ready?'运行正常':state.running?'检查中':'已暂停',esc((state.core.version||'sing-box').replace('sing-box version ','sing-box '))],['nodes','节点',state.nodes.length,'VLESS Reality / SS2022'],['users','可用用户',state.users.filter(u=>userStatus(u)==='active').length,`共 ${state.users.length} 位 · 独立身份`],['activity','剩余流量',trafficGB(state.users.reduce((n,u)=>n+(remainingBytes(u)??0),0)),'限额用户合计 · 不含不限量用户']].map(([i,k,v,h])=>`<div class="metric"><div class="metric-top"><span>${k}</span><span class="metric-icon">${icon(i)}</span></div><div class="metric-value"><strong class="${i==='power'?'local-core-value':''}">${v}</strong></div><div class="metric-foot">${h}</div></div>`).join('')}</div>`;}
function render(){if(!['live','demo'].includes(state.mode))return;$('#mode-badge').className='mode-badge'+(state.mode==='live'?' live':'');$('#mode-badge').innerHTML=`<span></span>${state.mode==='live'?'本机面板已连接':'交互预览'}`;$('#breadcrumb-page').textContent=pages[state.page];$('#nav-node-count').textContent=state.nodes.length;$('#nav-user-count').textContent=state.users.length;$('#nav-conversion-count').textContent=state.conversions.length;$('#logout-button').hidden=state.mode!=='live';$('#sidebar-hostname').textContent=state.machine.hostname||'本机 VPS';$('#sidebar-server-status').textContent=state.settings.publicHost||'请设置公网地址';$('#sidebar-dot').classList.toggle('online',!!state.core.ready);$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.page);a.setAttribute('aria-current',a.dataset.nav===state.page?'page':'false');});$('#main').innerHTML=({nodes:nodesView,users:usersView,conversions:conversionsView,logs:logsView,settings:settingsView}[state.page])();}
function empty(title,desc,action,label){return `<div class="empty-nodes"><div class="empty-icon">${icon('nodes')}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action?`<button class="button primary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function nodesView(){return `${heading('简单连接，从这里开始。','面板直接管理这台 VPS，保存节点后自动应用。','create-node','新建节点')}${banner()}${metrics()}<section class="panel node-panel"><div class="panel-heading"><div class="panel-title"><h2>我的节点</h2><span class="count-badge">${state.nodes.length}</span></div><div class="local-core-actions"><button class="button small" data-action="core-restart">${icon('refresh')}${state.running===false?'启动核心':'重启核心'}</button>${state.running!==false?'<button class="button small" data-action="core-stop">暂停</button>':''}</div></div><div class="node-toolbar"><div class="protocol-filters">${[['all','全部'],['vless','VLESS Reality'],['shadowsocks','SS2022']].map(([v,t])=>`<button class="filter${state.filter===v?' active':''}" data-filter="${v}">${t}</button>`).join('')}</div><div class="search-input">${icon('search')}<input id="node-search" type="search" placeholder="搜索节点…" aria-label="搜索节点" value="${esc(state.search)}"></div></div><div id="node-list">${nodeRows()}</div><div class="table-footer"><span>默认复制节点链接 · Clash / Mihomo 订阅按需使用</span><button class="text-button" data-action="goto" data-page="users">用户管理 ${icon('arrow')}</button></div></section><div class="protocol-note"><span class="protocol-note-icon">${icon('shield')}</span><div><h3>一台 VPS，一个简洁面板。</h3><p>节点、用户和双向流量都由本机直接管理。</p></div></div>`;}
function nodeEndpoint(n){const host=n.connectHost||state.settings.publicHost||'example.com';return(host.includes(':')?'['+host+']':host)+':'+(n.connectPort||n.port);}
function nodeRows(){const rows=state.nodes.filter(n=>(state.filter==='all'||n.protocol===state.filter)&&`${n.name} ${n.port} ${n.connectHost||''} ${n.connectPort||''}`.toLowerCase().includes(state.search.toLowerCase()));if(!rows.length)return empty('从第一个节点开始','创建 Reality 或 SS2022 节点，再为用户分配权限。','create-node','新建节点');return `<table class="node-table"><thead><tr><th>节点名称</th><th>协议</th><th>监听端口</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(n=>{const allowed=state.users.some(u=>userStatus(u)==='active'&&(u.nodeIds.includes('*')||u.nodeIds.includes(n.id)));const nodeCore=state.core.nodes?(state.core.nodes[n.id]||{}):state.core;const status=state.mode==='demo'?'未部署':!n.enabled?'已停用':!allowed?'待分配用户':nodeCore.ready?'运行中':nodeCore.error?'需要检查':'正在应用';return `<tr><td><div class="node-cell"><span class="node-protocol-icon${n.protocol==='shadowsocks'?' ss':''}">${icon(n.protocol==='vless'?'shield':'bolt')}</span><div><button class="node-title" data-action="edit-node" data-id="${esc(n.id)}">${esc(n.name)}</button><div class="node-subtitle">${esc(n.sni||n.method)}</div>${n.connectHost?'<div class="node-subtitle" title="'+esc(nodeEndpoint(n))+'">转发入口：'+esc(nodeEndpoint(n))+'</div>':''}</div></div></td><td><span class="protocol-badge">${n.protocol==='vless'?'VLESS Reality':'SS2022'}</span></td><td><span class="node-port">${n.port}</span></td><td><span class="node-state${status==='运行中'?' online':''}"><span class="tiny-dot"></span>${status}</span></td><td><div class="row-actions"><button class="icon-button" data-action="node-links" data-id="${esc(n.id)}" title="复制节点链接" aria-label="复制节点链接">${icon('copy')}</button><button class="icon-button" data-action="edit-node" data-id="${esc(n.id)}" aria-label="编辑节点">${icon('edit')}</button><button class="icon-button" data-action="node-menu" data-id="${esc(n.id)}" aria-label="更多操作">${icon('more')}</button></div></td></tr>`;}).join('')}</tbody></table>`;}

function usersView(){return`${heading('用户管理','独立连接凭据，一份清晰的双向流量额度。','create-user','新建用户')}${banner()}<section class="panel"><div class="panel-heading"><div class="panel-title"><h2>所有用户</h2><span class="count-badge">${state.users.length}</span></div><span class="panel-note">1 GB = 10⁹ 字节 · 上传 + 下载</span></div>${state.users.length?`<div class="user-table-wrap"><table class="user-table"><thead><tr><th>用户</th><th>剩余流量</th><th>到期 / 重置</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.users.map(u=>{
 const status=userStatus(u);
 return`<tr><td><div class="user-name-cell"><span class="user-avatar">${esc(u.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(u.name)}</strong><span>${esc(u.note||'独立凭据 · 双向配额')}</span></div></div></td><td><div class="usage-main"><strong>${trafficGB(remainingBytes(u))}</strong></div></td><td><div class="user-expiry">${date(u.expiresAt)}</div><div class="usage-breakdown">${u.cycle==='monthly'?`每月 ${u.resetDay} 日重置`:'手动重置'}</div></td><td><span class="state-pill${status==='active'?' green':status==='quota'||status==='expired'?' red':''}">${statusText[status]}</span></td><td><div class="user-row-actions"><button class="button small" data-action="user-links" data-id="${esc(u.id)}">${icon('copy')}节点链接</button><button class="button small" data-action="subscription" data-id="${esc(u.id)}">${icon('copy')}订阅</button><button class="icon-button" data-action="user-menu" data-id="${esc(u.id)}" aria-label="${esc(u.name)} 更多操作">${icon('more')}</button></div></td></tr>`;
 }).join('')}</tbody></table></div>`:empty('从第一个用户开始','设置额度和节点权限，获取个人节点链接。','create-user','新建用户')}<div class="table-footer"><span>${icon('info')}剩余量按上传 + 下载扣减，面板约每 5 秒刷新。</span></div></section>`;}
function conversionTime(value){if(!value)return'—';const d=new Date(typeof value==='number'?value*1000:value);return Number.isNaN(d.getTime())?'—':d.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function conversionsView(){return `${heading('订阅转换','粘贴手工节点链接，生成可直接导入 Mihomo 的订阅。','create-conversion','新建转换')}${state.mode==='demo'?`<div class="notice">${icon('info')}<span>演示订阅和 YAML 无法导入。转换记录仅保留到刷新页面；粘贴的原始链接在提交后丢弃，不发送请求、不写入浏览器存储。</span></div>`:''}<div class="notice">${icon('shield')}<span>支持 VLESS Reality 与 SS2022，每行一个节点链接。HK 等外部节点无需安装面板；转换记录独立保存，不创建本机节点或用户。</span></div><section class="panel conversion-panel"><div class="panel-heading"><div class="panel-title"><h2>转换记录</h2><span class="count-badge">${state.conversions.length}</span></div><span class="panel-note">Mihomo YAML</span></div>${state.conversions.length?`<div class="conversion-list">${state.conversions.map(c=>`<article class="conversion-row"><div class="conversion-summary"><span class="node-protocol-icon">${icon('refresh')}</span><div><button class="node-title" data-action="conversion-links" data-id="${esc(c.id)}">${esc(c.name)}</button><p>${Number(c.nodeCount)||0} 个节点 <span>·</span> 更新于 ${esc(conversionTime(c.updatedAt))}</p></div></div><div class="conversion-actions"><button class="button small" data-action="conversion-links" data-id="${esc(c.id)}">${icon('copy')}订阅链接</button><button class="icon-button" data-action="edit-conversion" data-id="${esc(c.id)}" aria-label="编辑 ${esc(c.name)}">${icon('edit')}</button><button class="icon-button" data-action="delete-conversion" data-id="${esc(c.id)}" aria-label="删除 ${esc(c.name)}">${icon('trash')}</button></div></article>`).join('')}</div>`:empty('把手工节点整理成一个订阅','粘贴 VLESS Reality / SS2022 链接，转换为 Mihomo 配置。','create-conversion','新建转换')}<div class="table-footer"><span>${icon('lock')}列表仅显示名称、节点数与更新时间，完整节点凭据仅在编辑时显示。</span></div></section>`;}
function demoConversionSource(count=2){return Array.from({length:Math.max(1,count)},(_,i)=>i%2?'ss://DEMO_ONLY_NOT_IMPORTABLE@hk.example.invalid:8388#SS2022%20%E7%A4%BA%E4%BE%8B':'vless://DEMO_ONLY_NOT_IMPORTABLE@hk.example.invalid:443?security=reality&type=tcp#Reality%20%E7%A4%BA%E4%BE%8B').join('\n');}
async function conversionDetail(id){if(state.mode==='live')return request('/api/conversions/'+encodeURIComponent(id));const c=state.conversions.find(c=>c.id===id);if(!c)throw new ApiError('转换记录不存在。');return {conversion:{...c,source:demoConversionSource(c.nodeCount)},paths:{clash:'/convert/DEMO_NOT_IMPORTABLE_'+id+'/clash.yaml'}};}
async function conversionForm(id){try{const c=id?(await conversionDetail(id)).conversion:{name:'',source:''};state.modal={type:'conversion',id};modal(id?'编辑转换':'新建转换','将手工节点链接转换为 Mihomo 订阅。',`<form id="conversion-form" autocomplete="off"><div class="modal-body"><div id="form-error"></div><div class="form-field"><label for="conversion-name">订阅名称</label><input id="conversion-name" class="input" name="name" maxlength="64" required value="${esc(c.name)}" placeholder="例如 HK 手工节点"><p class="field-hint">此名称用于面板中的记录；客户端订阅标题统一为“Singlite · Proxy”。</p></div><div class="form-field"><div class="conversion-source-label"><label for="conversion-source">节点链接（每行一个）</label>${state.mode==='demo'?'<button class="text-button" type="button" data-action="fill-conversion-demo">填入示例</button>':''}</div><textarea class="input conversion-source" id="conversion-source" name="source" rows="8" required spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="vless://…&#10;ss://…">${esc(c.source||'')}</textarea><p class="field-hint">支持 VLESS Reality、SS2022；请粘贴完整的节点分享链接，不支持远程订阅地址或其他协议。</p></div><div class="notice">${icon('lock')}<span>${state.mode==='demo'?'示例密钥无效，生成的订阅和 YAML 无法导入。提交后不会保留粘贴的原始链接，编辑时仅显示安全示例。':'节点链接包含连接凭据，将保存于当前面板。仅导出 Mihomo 格式；不会请求第三方转换服务。'}</span></div></div><footer class="modal-footer"><span class="modal-footer-note">${state.mode==='demo'?'原始链接不保存':'不改变外部节点的运行配置'}</span><button class="button" type="button" data-action="close-modal">取消</button><button class="button primary" type="submit">${icon('refresh')}${id?'保存转换':'生成订阅'}</button></footer></form>`,'',true);}catch(e){error(e);}}
async function saveConversion(form){const f=new FormData(form),id=state.modal.id,p={name:String(f.get('name')||'').trim(),source:String(f.get('source')||'').trim()};if(!p.name||!p.source){formError('请填写订阅名称和节点链接。');return;}await work($('[type=submit]',form),async()=>{try{let detail;if(state.mode==='demo'){const lines=p.source.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(lines.some(s=>! /^(vless|ss):\/\//i.test(s)))throw new ApiError('仅支持 VLESS Reality（vless://）和 SS2022（ss://）节点链接。');const now=Math.floor(Date.now()/1000),c={id:id||freshId(),name:p.name,nodeCount:lines.length,createdAt:now,updatedAt:now};if(id){const existing=state.conversions.find(c=>c.id===id);c.createdAt=existing.createdAt;Object.assign(existing,c);}else state.conversions.push(c);p.source='';detail=await conversionDetail(c.id);}else{detail=await request(id?'/api/conversions/'+encodeURIComponent(id):'/api/conversions',{method:id?'PUT':'POST',body:p});await refreshState();}closeModal();render();await conversionLinksModal(detail.conversion.id,detail);toast(state.mode==='demo'?'演示订阅已生成，原始节点链接已丢弃。':'Mihomo 订阅已保存。');}catch(e){formError(e.message);}});}
async function conversionLinksModal(id,detail){try{const r=detail||await conversionDetail(id),c=r.conversion,path=r.paths.clash,link=(state.mode==='demo'?'https://panel.example.invalid':location.origin)+path;state.modal={type:'conversion-links',id,link,path};modal('Mihomo 订阅',`${esc(c.name)} · ${Number(c.nodeCount)||0} 个节点`,`<div class="modal-body"><div class="notice">${icon('lock')}<span>${state.mode==='demo'?'这是演示订阅，链接与下载的 YAML 均无法导入真实节点。':'持有此链接即可获取节点凭据，请妥善保管。支持使用 Mihomo 内核的客户端。'}</span></div><div class="copy-field"><label>订阅地址</label><code>${esc(link)}</code></div><p class="field-hint">在客户端添加远程订阅，粘贴此地址。订阅标题固定为“Singlite · Proxy”，不发送流量额度或到期信息。</p><div class="share-action-row"><button class="button small" data-action="edit-conversion" data-id="${esc(id)}">${icon('edit')}编辑源链接</button>${state.mode==='live'?`<a class="button small" href="${esc(path)}" download="Singlite · Proxy.yaml">${icon('download')}下载 YAML</a>`:'<button class="button small" data-action="download-conversion-demo">'+icon('download')+'下载示例 YAML</button>'}</div><p class="field-hint">删除转换记录仅使此订阅地址失效，HK 等外部服务器上的原节点仍然有效。</p></div>`,`<footer class="modal-footer"><button class="button" data-action="close-modal">关闭</button><button class="button primary" data-action="copy-conversion-link">${icon('copy')}复制${state.mode==='demo'?'示例':'订阅'}链接</button></footer>`,true);}catch(e){error(e);}}
function downloadDemoConversion(){const blob=new Blob(['# Singlite · Proxy\n# 演示文件：没有真实节点，无法导入使用。\n# 粘贴的原始节点链接不会写入此文件。\nproxies: []\n'],{type:'text/yaml;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Singlite · Proxy-demo.yaml';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载示例 YAML，无法导入真实节点。');}
function logsView(){return `${heading('运行日志','查看本机 sing-box 的最近运行记录。')}<section class="panel log-panel"><div class="panel-heading"><h2>本机日志</h2><button class="button small" data-action="refresh-logs">${icon('refresh')}刷新</button></div><pre class="log-content">${esc(state.logs.join('\n')||'暂无日志。')}</pre></section>`;}
function settingsView(){const m=state.machine.memory;return `${heading('面板设置','这台 VPS 的连接地址与用量规则。')}${banner()}<div class="settings-layout"><section class="panel section-panel"><div class="panel-heading"><h2>节点公网地址</h2></div><form id="settings-form" class="local-settings-form"><div class="form-field"><label for="public-host">这台 VPS 的公网 IP / 直连域名</label><input id="public-host" class="input" name="publicHost" required maxlength="253" value="${esc(state.settings.publicHost||'')}"><p class="field-hint">未单独填写前置机地址的节点使用此地址，不含协议和端口；使用 CDN 时请改为这台 VPS 的公网 IP。</p></div><button class="button primary" type="submit">${icon('check')}保存地址</button></form><dl class="settings-definitions"><div><dt>本机</dt><dd>${esc(state.machine.hostname||'—')}</dd></div><div><dt>CPU / 内存</dt><dd>${Number.isFinite(state.machine.cpu)?state.machine.cpu+'%':'—'} / ${m?bytes(m.used)+' / '+bytes(m.total):'—'}</dd></div><div><dt>流量口径</dt><dd>上传 + 下载；1 GB = 10⁹ 字节</dd></div><div><dt>月度重置</dt><dd>北京时间 00:00；不足重置日时按月末</dd></div><div><dt>配额执行</dt><dd>本机约每秒采样。超额、到期或停用会重新加载核心，可能短暂断开本机其他连接。</dd></div><div><dt>账单差异</dt><dd>统计代理用户字节，厂商可能另计协议开销和其他服务流量。</dd></div></dl></section><aside class="panel settings-note">${icon('terminal')}<h3>只安装一次。</h3><p>上传源码包，执行 install.sh。完成后即可在这个面板创建节点与用户。</p><button class="button primary" data-action="guide">部署指南 ${icon('arrow')}</button></aside></div>`;}

function navigate(page){if(!pages[page])return;state.page=page;if(location.hash!=='#'+page)location.hash=page;closeSidebar();closeMenu();render();if(page==='logs')loadLogs();}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');}
function toast(message,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.setAttribute('role',error?'alert':'status');n.innerHTML=icon(error?'info':'check')+`<span>${esc(message)}</span>`;$('#toast-root').append(n);setTimeout(()=>n.remove(),error?6500:4200);}
function error(e){if(e.status===401){closeModal();login('登录已过期，请重新登录。');}else toast(e.message||'操作失败，请重试。',true);}
async function work(button,fn){if(busy)return;busy=true;if(button){button.disabled=true;button.setAttribute('aria-busy','true');}try{await fn();}catch(e){error(e);}finally{busy=false;if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}}}
function modal(title,subtitle,body,footer='',wide=false){closeMenu();returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal${wide?' wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-modal" aria-label="关闭对话框">${icon('close')}</button></header>${body}${footer}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>($('.modal [autofocus]')||$('.modal input:not([disabled])')||$('.modal'))?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';state.modal=null;if(returnFocus?.isConnected)returnFocus.focus();returnFocus=null;}
const footer=label=>`<footer class="modal-footer"><span class="modal-footer-note">${state.mode==='demo'?'演示修改仅保存在浏览器':'保存后自动应用到本机'}</span><button class="button" type="button" data-action="close-modal">取消</button><button class="button primary" type="submit">${icon('check')}${label}</button></footer>`;
function formError(message){const e=$('#form-error');if(e)e.innerHTML=`<div class="form-error" role="alert">${esc(message)}</div>`;else toast(message,true);}
function nextPort(start){let p=start;while(state.nodes.some(n=>n.port===p))p++;return p;}
function nodeForm(id){const n=state.nodes.find(n=>n.id===id)||{name:'',protocol:'vless',port:nextPort(8443),enabled:true,sni:'www.amd.com',method:'2022-blake3-aes-128-gcm'};state.modal={type:'node',id,protocol:n.protocol};modal(id?'编辑节点':'新建节点','保存后自动应用到这台 VPS。',`<form id="node-form"><div class="modal-body"><div id="form-error"></div><div class="form-field"><label for="node-name">节点名称</label><input id="node-name" class="input" name="name" maxlength="64" required value="${esc(n.name)}"></div><div class="segmented">${[['vless','VLESS Reality'],['shadowsocks','SS2022']].map(([p,t])=>`<button type="button" class="protocol-choice${n.protocol===p?' active':''}" data-protocol="${p}"${id?' disabled':''}><strong>${t}</strong></button>`).join('')}</div><div class="form-field"><label for="node-port">监听端口</label><input id="node-port" class="input" name="port" type="number" min="1" max="65535" required value="${n.port}"><p class="field-hint">本机实际监听的端口，请在安全组和防火墙放行。80 / 443 / 8787 / 10085 为保留端口。</p></div><div id="protocol-fields">${protocolFields(n.protocol,n)}</div><div id="node-common-fields">${commonNodeFields(n)}</div><label class="check-line"><input type="checkbox" name="enabled"${n.enabled?' checked':''}>启用节点</label></div>${footer('保存节点')}</form>`);}
async function saveNode(form){const f=new FormData(form),id=state.modal.id,p={name:String(f.get('name')).trim(),protocol:state.modal.protocol,port:Number(f.get('port')),enabled:f.has('enabled'),connectHost:String(f.get('connectHost')||'').trim(),connectPort:f.get('connectPort')?Number(f.get('connectPort')):null};if(p.protocol==='vless')p.sni=String(f.get('sni')).trim();else p.method=String(f.get('method'));if(p.connectPort!==null&&!p.connectHost){formError('请同时填写前置机 IP / 域名，或清空前置机端口以恢复直连。');return;}await work($('[type=submit]',form),async()=>{try{if(state.mode==='demo'){if(id)Object.assign(state.nodes.find(n=>n.id===id),p);else state.nodes.push({...p,id:freshId()});eventLog('保存示例节点');}else{await request(id?'/api/nodes/'+id:'/api/nodes',{method:id?'PUT':'POST',body:p});await refreshState();}closeModal();render();toast('已保存，正在应用本机配置。');}catch(e){formError(e.message);}});}
function protocolFields(p,n={}){return p==='vless'?`<div class="form-field"><label for="node-sni">Reality 伪装域名（SNI）</label><input class="input" id="node-sni" name="sni" maxlength="253" required value="${esc(n.sni||'www.amd.com')}"><div class="field-hint">目标需能从 VPS 访问，并支持 TLS 1.3。</div></div>`:`<div class="form-field"><label for="node-method">加密方式</label><select class="select" id="node-method" name="method"><option value="2022-blake3-aes-128-gcm">2022-blake3-aes-128-gcm</option><option value="2022-blake3-aes-256-gcm"${n.method==='2022-blake3-aes-256-gcm'?' selected':''}>2022-blake3-aes-256-gcm</option></select></div>`;}
function commonNodeFields(n={}){return `<div class="form-field"><label for="connect-host">前置机 IP / 域名（可选）</label><input class="input" id="connect-host" name="connectHost" maxlength="253" value="${esc(n.connectHost||'')}" placeholder="例如 203.0.113.10，直连时留空"><div class="field-hint">节点链接和订阅使用此前置地址；本机仍监听上方端口。只填写地址时，连接端口沿用监听端口。</div></div><div class="form-field"><label for="connect-port">前置机端口（可选）</label><input class="input" id="connect-port" name="connectPort" type="number" min="1" max="65535" value="${n.connectPort??''}" placeholder="留空使用本机监听端口"><div class="field-hint">前置机需透明转发到本机监听端口，Reality 的 SNI 保持不变。使用 UDP 时，请同时配置 UDP 转发。</div></div>`;}

function userForm(id){const u=state.users.find(u=>u.id===id)||{name:'',note:'',enabled:true,quotaBytes:100*GB,cycle:'monthly',resetDay:1,nodeIds:['*'],expiresAt:null};state.modal={type:'user',id};const expiry=u.expiresAt?new Date((u.expiresAt+8*3600)*1000).toISOString().slice(0,10):'';modal(id?'编辑用户':'新建用户','上传 + 下载，本机所有授权节点共用一份配额。',`<form id="user-form"><div class="modal-body"><div id="form-error"></div><div class="form-grid"><div class="form-field"><label for="user-name">用户名称</label><input class="input" id="user-name" name="name" maxlength="64" required value="${esc(u.name)}"></div><div class="form-field"><label for="user-quota">双向流量额度（GB）</label><input class="input" id="user-quota" name="quotaGB" type="number" min="0" max="1000000" step="0.001" required value="${u.quotaBytes/GB}"><div class="field-hint">上传 + 下载；0 表示不限量。</div></div><div class="form-field"><label for="user-expiry">到期日期（北京时间）</label><input class="input" id="user-expiry" name="expiry" type="date" value="${expiry}"><div class="field-hint">留空长期有效；所选日期 23:59:59 到期。</div></div><div class="form-field"><label for="user-cycle">流量重置周期</label><select class="select" name="cycle" id="user-cycle"><option value="monthly">每月自动重置</option><option value="never"${u.cycle==='never'?' selected':''}>仅手动重置</option></select></div><div class="form-field"><label for="user-day">每月重置日</label><input class="input" id="user-day" name="resetDay" type="number" min="1" max="31" required value="${u.resetDay}"><div class="field-hint">北京时间 00:00，不足该日按月末。</div></div><div class="form-field"><label for="user-note">备注</label><input class="input" id="user-note" name="note" maxlength="256" value="${esc(u.note||'')}"></div></div><div class="form-field"><span class="form-label">节点权限</span><label class="check-line"><input type="checkbox" id="user-all-nodes" name="allNodes"${u.nodeIds.includes('*')?' checked':''}>全部节点（包括以后新增的节点）</label><div class="node-access-list" id="node-access-list"${u.nodeIds.includes('*')?' hidden':''}>${state.nodes.map(n=>`<label class="check-line"><input type="checkbox" name="nodeIds" value="${esc(n.id)}"${u.nodeIds.includes(n.id)?' checked':''}>${esc(n.name)}</label>`).join('')||'<p class="field-hint">尚无节点，可先创建用户，稍后分配。</p>'}</div></div><label class="check-line"><input type="checkbox" name="enabled"${u.enabled?' checked':''}>启用用户</label><div class="notice">${icon('info')}<span>每人独立 UUID / SS2022 身份。到期或用尽额度后在节点端停用；变更仅应用到相关节点，可能短暂中断这些节点的现有连接。</span></div></div>${footer(id?'保存用户':'创建用户')}</form>`,'',true);}
async function saveUser(form){const f=new FormData(form),id=state.modal.id,p={name:String(f.get('name')).trim(),note:String(f.get('note')||'').trim(),quotaGB:Number(f.get('quotaGB')),cycle:String(f.get('cycle')),resetDay:Number(f.get('resetDay')),expiresAt:f.get('expiry')?Math.floor(new Date(f.get('expiry')+'T23:59:59+08:00').getTime()/1000):null,nodeIds:f.has('allNodes')?['*']:f.getAll('nodeIds'),enabled:f.has('enabled')};if(!Number.isFinite(p.quotaGB)||p.quotaGB<0||p.quotaGB>1e6){formError('配额格式无效。');return;}await work($('[type=submit]',form),async()=>{try{let uid=id;if(state.mode==='demo'){if(id)Object.assign(state.users.find(u=>u.id===id),p,{quotaBytes:p.quotaGB*GB});else{uid=freshId();state.users.push({...p,id:uid,quotaBytes:p.quotaGB*GB,uploadBytes:0,downloadBytes:0,usedBytes:0});}eventLog('保存示例用户');}else{const r=await request(id?'/api/users/'+id:'/api/users',{method:id?'PUT':'POST',body:p});uid=r.user.id;await refreshState();}closeModal();render();if(!id)await linksModal(uid);else toast('用户已保存，权限和配额自动应用到本机。');}catch(e){formError(e.message);}});}
async function linksModal(id,nodeId=''){const users=state.users.filter(u=>userStatus(u)==='active'&&(!nodeId||u.nodeIds.includes('*')||u.nodeIds.includes(nodeId)));if(!id)id=users[0]?.id;const user=state.users.find(u=>u.id===id);if(!user){toast('请先创建用户并分配节点权限。');return;}try{const data=state.mode==='demo'?{links:state.nodes.filter(n=>n.enabled&&(user.nodeIds.includes('*')||user.nodeIds.includes(n.id))).map(n=>({nodeId:n.id,name:n.name,uri:(n.protocol==='vless'?'vless://DEMO_UUID@':'ss://DEMO_KEY@')+nodeEndpoint(n)}))}:await request('/api/users/'+id+'/links');const links=data.links.filter(n=>!nodeId||n.nodeId===nodeId);state.modal={type:'links',id,nodeId,links};modal('节点链接','直接导入兼容的客户端，流量计入所选用户。',`<div class="modal-body"><div class="form-field"><label for="link-user">使用用户</label><select class="select" id="link-user">${users.map(u=>`<option value="${esc(u.id)}"${u.id===id?' selected':''}>${esc(u.name)}</option>`).join('')}</select></div>${data.warning?`<div class="notice">${esc(data.warning)}</div>`:''}${links.length?links.map((n,i)=>`<div class="copy-field"><label>${esc(n.name)}</label><code>${esc(n.uri)}</code><button class="button small" data-action="copy-node-link" data-index="${i}">${icon('copy')}复制节点链接</button></div>`).join(''):'<div class="notice">请先创建并启用节点，为用户分配权限。</div>'}${state.mode==='demo'?'<p class="field-hint">演示链接无法连接真实节点。</p>':''}</div>`,`<footer class="modal-footer"><button class="button" data-action="close-modal">关闭</button><button class="button" data-action="subscription" data-id="${esc(id)}">可选：Clash / Mihomo 订阅</button>${links.length?'<button class="button primary" data-action="copy-all-node-links">复制全部</button>':''}</footer>`,true);}catch(e){error(e);}}

async function subscriptionModal(id){let u=state.users.find(u=>u.id===id);if(!u)return;try{const r=state.mode==='demo'?{path:'/sub/DEMO_NOT_A_REAL_SUBSCRIPTION/clash.yaml'}:await request('/api/users/'+id+'/subscription');if(r.user)u=r.user;const link=(state.mode==='demo'?'https://panel.example.com':location.origin)+r.path;state.modal={type:'subscription',id,link};modal('个人订阅',`${esc(u.name)} · Clash / Mihomo`, `<div class="modal-body"><div class="notice">${icon('lock')}<span>${state.mode==='demo'?'这是演示链接，无法导入真实节点。':'持有链接即可获取该用户的节点配置，请妥善保管。适用于支持 Reality、SS2022 的 Mihomo 内核客户端。'}</span></div><div class="subscription-stats"><div><span>剩余流量</span><strong>${trafficGB(remainingBytes(u))}</strong></div><div><span>到期</span><strong>${date(u.expiresAt)}</strong></div></div><div class="copy-field"><label>订阅地址</label><code id="subscription-link">${esc(link)}</code></div><p class="field-hint">在客户端“订阅 / 配置”中新增远程订阅，粘贴此地址。订阅自动汇总该用户有权限使用的本机节点。订阅标题统一为“Singlite · Proxy”，客户端不再接收流量和到期信息。</p>${userStatus(u)!=='active'?`<div class="form-error">当前状态：${statusText[userStatus(u)]}。恢复用户后才能拉取订阅与连接节点。</div>`:''}<p class="field-hint">从旧版升级时，请在客户端删除旧订阅后重新导入一次，清除旧名称、流量和到期缓存；导入时保留自动名称。剩余量和有效期请在本面板查看。</p><div class="share-action-row"><button class="button small" data-action="rotate-user" data-id="${esc(id)}">${icon('refresh')}重置订阅地址</button>${state.mode==='live'?`<a class="button small" href="${esc(r.path)}" download="Singlite · Proxy.yaml">${icon('download')}下载配置</a>`:''}</div><p class="field-hint">重置仅更新订阅地址；已获取的节点凭据仍有效。要停止连接，请停用该用户。</p></div>`,`<footer class="modal-footer"><button class="button" data-action="close-modal">关闭</button><button class="button primary" data-action="copy-subscription">${icon('copy')}复制${state.mode==='demo'?'示例':'订阅'}链接</button></footer>`,true);}catch(e){error(e);}}
function closeMenu(){$('#action-menu')?.remove();}
function menu(type,id,button){closeMenu();const items=type==='node'?[['edit-node','edit','编辑节点'],['toggle-node','power','切换启用状态'],['delete-node','trash','删除节点']]:[['edit-user','edit','编辑用户'],['toggle-user','power','切换启用状态'],['reset-user','refresh','重置流量额度'],['rotate-user','copy','重置订阅地址'],['delete-user','trash','删除用户']];const el=document.createElement('div');el.id='action-menu';el.className='menu-popover';el.innerHTML=items.map(([a,i,t])=>`<button data-action="${a}" data-id="${esc(id)}">${icon(i)}${t}</button>`).join('');document.body.append(el);const r=button.getBoundingClientRect();el.style.left=Math.max(10,Math.min(innerWidth-el.offsetWidth-10,r.right-el.offsetWidth))+'px';el.style.top=(r.bottom+el.offsetHeight+8>innerHeight?Math.max(10,r.top-el.offsetHeight-5):r.bottom+5)+'px';$('button',el).focus();}
function confirmAction(action,id){closeMenu();const record=(action.endsWith('node')?state.nodes:action.endsWith('conversion')?state.conversions:state.users).find(n=>n.id===id);const title=action==='core-stop'?'暂停本机核心？':action.startsWith('delete')?'确认删除？':action==='reset-user'?'重置流量额度？':'重置订阅地址？';const desc=action==='delete-conversion'?'此订阅地址将失效，转换记录和保存的源链接会被删除；HK 等外部服务器上的原节点仍然有效。':action==='core-stop'?'暂停本机所有代理连接，网页面板仍可访问。':action==='rotate-user'?'旧订阅地址会失效，已导入的节点凭据仍有效。停止连接请停用用户。':action==='reset-user'?'上传和下载统计同时归零，剩余流量恢复为总额度。':'保存后自动应用到本机。';state.modal={type:'confirm',action,id};modal(title,esc(record?.name||'这台 VPS'),`<div class="modal-body"><p>${desc}</p></div>`,`<footer class="modal-footer"><button class="button" data-action="close-modal">取消</button><button class="button danger" data-action="confirmed">确认</button></footer>`);}
async function mutate(action,id){if(action.startsWith('core-')){if(state.mode==='live')await request('/api/core',{method:'POST',body:{action:action==='core-stop'?'stop':'restart'}});else{state.running=action!=='core-stop';persist();}}else{const kind=action.endsWith('node')?'nodes':action.endsWith('conversion')?'conversions':'users',item=state[kind].find(n=>n.id===id);if(state.mode==='demo'){if(action.startsWith('delete'))state[kind]=state[kind].filter(n=>n.id!==id);else if(action.startsWith('toggle'))item.enabled=!item.enabled;else if(action==='reset-user'){item.uploadBytes=0;item.downloadBytes=0;}eventLog('示例操作：'+action);}else{const path='/api/'+kind+'/'+id;if(action.startsWith('delete'))await request(path,{method:'DELETE'});else if(action.startsWith('toggle'))await request(path,{method:'PUT',body:{enabled:!item.enabled}});else await request(path+(action==='reset-user'?'/reset-traffic':'/rotate-token'),{method:'POST',body:{}});}}if(state.mode==='live')await refreshState();closeModal();render();if(action==='rotate-user')await subscriptionModal(id);else toast(action==='delete-conversion'?'转换订阅已删除，外部原节点仍然有效。':'已保存，本机自动应用。');}

async function loadLogs(){if(state.mode==='live'){try{state.logs=(await request('/api/logs')).lines||[];}catch(e){error(e);return;}}if(state.page==='logs')render();}
async function copy(value,message='已复制。'){try{if(navigator.clipboard?.writeText&&isSecureContext)await navigator.clipboard.writeText(value);else{const t=document.createElement('textarea');t.value=value;t.style.cssText='position:fixed;left:-9999px';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw Error();}toast(message);}catch{toast('未能复制，请手动选择并复制。',true);}}
function guide(){state.modal={type:'guide'};modal('单机部署，只安装一次。','一个面板对应这台 VPS。',`<div class="modal-body"><p>将完整源码包通过 SSH / SFTP 上传到 VPS 的 /root，解压后执行：</p><pre class="guide-code">cd /root
tar -xzf singlite-panel.tar.gz
cd singlite-single
bash install.sh --with-caddy</pre><p>填写域名和管理员（密码至少 6 位），安装后登录并创建节点与用户。节点保存后自动应用。</p><p>80 / 443 已有网站时使用 <code>--existing-proxy</code>，并将 HTTPS 站点反代到 127.0.0.1:8787。</p><div class="guide-download"><a class="button primary" href="./singlite-panel.tar.gz" download>下载单机源码</a><a class="button" href="./deploy-guide.html" target="_blank" rel="noopener">完整中文教程</a></div></div>`,`<footer class="modal-footer"><button class="button" data-action="close-modal">明白了</button></footer>`);}

document.addEventListener('submit',async e=>{if(!['settings-form','node-form','user-form','conversion-form','login-form'].includes(e.target.id))return;e.preventDefault();const f=e.target;if(f.id==='settings-form')await work($('[type=submit]',f),async()=>{const p=Object.fromEntries(new FormData(f));if(state.mode==='demo'){state.settings=p;persist();}else{await request('/api/settings',{method:'PUT',body:p});await refreshState();}render();toast('节点公网地址已保存。');});else if(f.id==='node-form')await saveNode(f);else if(f.id==='user-form')await saveUser(f);else if(f.id==='conversion-form')await saveConversion(f);else await work($('[type=submit]',f),async()=>{try{const p=Object.fromEntries(new FormData(f)),r=await request('/api/login',{method:'POST',body:p});state.csrf=r.csrf;await refreshState();showApp();}catch(e){login(e.message);}});});
document.addEventListener('input',e=>{if(e.target.id==='node-search'){state.search=e.target.value;$('#node-list').innerHTML=nodeRows();}});
document.addEventListener('change',e=>{if(e.target.id==='user-all-nodes')$('#node-access-list').hidden=e.target.checked;});
document.addEventListener('click',async e=>{
 const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return;}
 const protocol=e.target.closest('[data-protocol]');if(protocol&&state.modal?.type==='node'&&!state.modal.id){state.modal.protocol=protocol.dataset.protocol;$$('[data-protocol]').forEach(p=>p.classList.toggle('active',p===protocol));$('#protocol-fields').innerHTML=protocolFields(state.modal.protocol);$('#node-port').value=nextPort(state.modal.protocol==='vless'?8443:8388);return;}
 const button=e.target.closest('[data-action]');if(!button){if(!e.target.closest('#action-menu'))closeMenu();if(e.target.classList.contains('modal-backdrop')&&!busy)closeModal();return;}
 const a=button.dataset.action,id=button.dataset.id;if(busy)return;
 if(['delete-node','delete-user','delete-conversion','reset-user','rotate-user','core-stop'].includes(a)){confirmAction(a,id);return;}
 if(a==='retry')await bootstrap();else if(a==='guide')guide();else if(a==='goto')navigate(button.dataset.page);else if(a==='close-modal')closeModal();else if(a==='create-node'||a==='edit-node')nodeForm(id);else if(a==='create-user'||a==='edit-user')userForm(id);else if(a==='create-conversion'||a==='edit-conversion')await work(button,()=>conversionForm(id));else if(a==='conversion-links')await work(button,()=>conversionLinksModal(id));else if(a==='fill-conversion-demo'){$('#conversion-source').value=demoConversionSource();$('#conversion-source').focus();}else if(a==='copy-conversion-link')await copy(state.modal.link,state.mode==='demo'?'示例链接已复制，无法导入真实节点。':'Mihomo 订阅链接已复制。');else if(a==='download-conversion-demo')downloadDemoConversion();else if(a==='node-links')await work(button,()=>linksModal(null,id));else if(a==='user-links')await work(button,()=>linksModal(id));else if(a==='copy-node-link')await copy(state.modal.links[Number(button.dataset.index)].uri,'节点链接已复制。');else if(a==='copy-all-node-links')await copy(state.modal.links.map(link=>link.uri).join('\n'),'节点链接已复制，每行一个。');else if(a==='subscription')await work(button,()=>subscriptionModal(id));else if(a.endsWith('-menu'))menu(a.split('-')[0],id,button);else if(a.startsWith('toggle-'))await work(button,()=>mutate(a,id));else if(a==='confirmed'){const m={...state.modal};await work(button,()=>mutate(m.action,m.id));}else if(a==='copy-subscription')await copy(state.modal.link,state.mode==='demo'?'示例链接已复制，无法连接真实节点。':'个人订阅链接已复制。');else if(a==='core-restart')await work(button,()=>mutate(a));else if(a==='refresh-logs')await work(button,loadLogs);else if(a==='logout')await work(button,async()=>{await request('/api/logout',{method:'POST',body:{}});state.csrf='';closeModal();login();});
});
$$('[data-nav]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();navigate(a.dataset.nav);}));
$('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#sidebar-scrim').classList.toggle('open',open);$('#mobile-menu').setAttribute('aria-expanded',String(open));});$('#sidebar-scrim').addEventListener('click',closeSidebar);
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]&&state.page!==p)navigate(p);});window.addEventListener('resize',closeMenu);window.addEventListener('scroll',closeMenu,{passive:true});
document.addEventListener('change',async e=>{if(e.target.id==='link-user'&&!busy){const nodeId=state.modal.nodeId;await work(e.target,()=>linksModal(e.target.value,nodeId));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!busy){closeModal();closeMenu();closeSidebar();}if(e.key==='Tab'&&$('.modal')){const items=$$('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]',$('.modal')).filter(n=>n.offsetParent!==null),first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
setInterval(async()=>{if(state.mode!=='live'||$('#app').hidden||busy||state.modal||polling||document.hidden||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;polling=true;try{await refreshState();render();}catch(e){error(e);}finally{polling=false;}},5000);
bootstrap();
})();
